import torch
import torch.nn as nn
import torch.nn.functional as F



class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, a, b):
        return torch.matmul(a, b)


def get_inputs():
    a = torch.randn(32, 8192, dtype=torch.bfloat16)
    b = torch.randn(8192, 8192, dtype=torch.bfloat16)
    return [a, b]


def get_init_inputs():
    return []


def run(a, b):
    model = Model()
    device = a.device
    model = model.to(device)
    model.eval()
    with torch.no_grad():
        result = model(a, b)
    return result


def _legacy_gen_inputs(axes, device):
    inputs = get_inputs()
    result = {}
    result['a'] = inputs[0].to(device) if hasattr(inputs[0], 'to') else inputs[0]
    result['b'] = inputs[1].to(device) if hasattr(inputs[1], 'to') else inputs[1]
    return result

def gen_inputs(ctx, device):
    del ctx
    return _legacy_gen_inputs({'M': 32, 'K': 8192, 'N': 8192}, device)
